solutions.naive:
class Solution:
    def firstUniqChar(self, s: str) -> int:
        for i, ch in enumerate(s):
            count = 0
            for other in s:
                if other == ch:
                    count += 1
            if count == 1:
                return i
        return -1

solutions.better:
from collections import Counter

class Solution:
    def firstUniqChar(self, s: str) -> int:
        counts = Counter(s)
        for i, ch in enumerate(s):
            if counts[ch] == 1:
                return i
        return -1

